import csv
import io
import re


def _fallback_parse(raw_csv):
    rows = []
    row = []
    field = []
    in_quotes = False
    field_started = False
    i = 0
    n = len(raw_csv)

    while i < n:
        ch = raw_csv[i]

        if in_quotes:
            if ch == '"':
                if i + 1 < n and raw_csv[i + 1] == '"':
                    field.append('"')
                    i += 2
                    continue
                in_quotes = False
                i += 1
                continue
            field.append(ch)
            i += 1
            continue

        if ch == '"' and not field_started:
            in_quotes = True
            field_started = True
            i += 1
            continue

        if ch == "\t":
            row.append("".join(field))
            field = []
            field_started = False
            i += 1
            continue

        if ch == "\r" or ch == "\n":
            row.append("".join(field))
            rows.append(row)
            row = []
            field = []
            field_started = False
            if ch == "\r" and i + 1 < n and raw_csv[i + 1] == "\n":
                i += 2
            else:
                i += 1
            continue

        field.append(ch)
        field_started = True
        i += 1

    if field_started or field or row or in_quotes:
        row.append("".join(field))
        rows.append(row)

    return rows


def _read_rows(raw_csv):
    previous_limit = csv.field_size_limit()
    try:
        try:
            csv.field_size_limit(100000000)
        except (OverflowError, TypeError):
            pass

        rows = []
        reader = csv.reader(
            io.StringIO(raw_csv, newline=""),
            delimiter="\t",
            quotechar='"',
            doublequote=True,
            skipinitialspace=False,
            strict=False,
        )
        try:
            for row in reader:
                rows.append([str(value) for value in row])
            return rows
        except csv.Error:
            return _fallback_parse(raw_csv)
    finally:
        try:
            csv.field_size_limit(previous_limit)
        except (OverflowError, TypeError):
            pass


def _header_score(row, index, rows, expected_width):
    if not row:
        return -1000.0

    width_difference = abs(len(row) - expected_width)
    if width_difference > 2:
        return -1000.0 - width_difference

    score = 8.0 if len(row) == expected_width else -4.0 * width_difference
    nonempty = 0
    label_like = 0
    data_like = 0

    for value in row:
        text = value.strip()
        if not text:
            continue

        nonempty += 1

        if len(text) <= 80 and re.match(
            r"^[A-Za-z][A-Za-z0-9 _./()'&+#%-]*$", text
        ):
            label_like += 1

        if re.match(r"^[+-]?\d+(?:[.,]\d+)?$", text):
            data_like += 1
        elif re.match(r"^\d{1,4}[-/]\d{1,2}[-/]\d{1,4}$", text):
            data_like += 1
        elif re.match(r"^\d{1,2}:\d{2}(?::\d{2})?$", text):
            data_like += 1
        elif re.match(r"^[A-Za-z][A-Za-z0-9+.-]*://", text):
            data_like += 1
        elif re.match(r"^[\$€£¥]\s*\d", text):
            data_like += 1

    score += nonempty * 0.8
    score += label_like * 1.5
    score -= data_like * 3.0
    score -= index * 0.08

    following = rows[index + 1:index + 5]
    if following:
        consistent = sum(
            1 for candidate in following
            if abs(len(candidate) - expected_width) <= 1
        )
        score += consistent * 1.5

    return score


def _find_header(rows, expected_width):
    if not rows:
        return 0

    candidates = []
    limit = min(len(rows), 100)

    for index in range(limit):
        row = rows[index]
        if not row or all(value.strip() == "" for value in row):
            continue
        score = _header_score(row, index, rows, expected_width)
        candidates.append((score, -index, index))

    if not candidates:
        return 0

    candidates.sort(reverse=True)
    return candidates[0][2]


def _normalize_row(row, width):
    values = [str(value) for value in row]

    if len(values) < width:
        values.extend([""] * (width - len(values)))
    elif len(values) > width:
        values = values[:width - 1] + ["\t".join(values[width - 1:])]

    return values


def parse_csv(raw_csv: str):
    if raw_csv is None:
        raw_csv = ""
    elif not isinstance(raw_csv, str):
        raw_csv = str(raw_csv)

    if raw_csv.startswith("\ufeff"):
        raw_csv = raw_csv[1:]

    expected_width = 9
    parsed_rows = _read_rows(raw_csv)

    if not parsed_rows:
        return {"columns": [], "rows": []}

    header_index = _find_header(parsed_rows, expected_width)
    columns = _normalize_row(parsed_rows[header_index], expected_width)
    data_rows = [
        _normalize_row(row, expected_width)
        for row in parsed_rows[header_index + 1:]
    ]

    return {"columns": columns, "rows": data_rows}
